import React, { useState } from 'react';

const MicroFrontendShell = () => {
  const [activeMicroFrontend, setActiveMicroFrontend] = useState<string | null>(null);

  const microFrontendConfigs: MicroFrontendConfig[] = [
    { name: 'Dashboard', url: 'https://dashboard.example.com' },
    { name: 'Settings', url: 'https://settings.example.com' },
    { name: 'Profile', url: 'https://profile.example.com' }
  ];

  const selectMicroFrontend = (name: string) => {
    setActiveMicroFrontend(name);
  };

  return (
    <div className="shell-container">
      <h1>Micro-frontend Shell</h1>
      <p>Active: {activeMicroFrontend || 'None selected'}</p>
      <div>
        {microFrontendConfigs.map((config) => (
          <button key={config.name}>
            {config.name}
          </button>
        ))}
      </div>
    </div>
  );
};

interface MicroFrontendConfig {
  name: string;
  url: string;
}
